values (md5('package-workout:ana-abc:0')::uuid, md5('package:ana-abc')::uuid, 0, 'A – Peito e tríceps', 'Empurrar: peito com ênfase no supino e tríceps no final.', 'Treino de peito e tríceps com volume moderado. Descanse 90 segundos entre as séries dos exercícios compostos e 60 segundos nos isolados. Quando completar todas as repetições com boa técnica em duas sessões seguidas, aumente a carga em 2 a 5%.', '[{"category":"strength","name":"Supino reto","sets":4,"reps":10,"weightKg":40,"note":"Desça a barra até tocar o peito e mantenha as escápulas juntas no banco."},{"category":"strength","name":"Supino inclinado com halteres","sets":3,"reps":12,"weightKg":16},{"category":"strength","name":"Crucifixo na máquina","sets":3,"reps":12,"weightKg":30},{"category":"strength","name":"Tríceps na polia","sets":4,"reps":12,"weightKg":20,"note":"Cotovelos colados ao corpo; só o antebraço se move."}]'::jsonb)
on conflict (package_id, position) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, exercises = excluded.exercises;

insert into public.package_workouts (id, package_id, position, name, summary, description, exercises)
values (md5('package-workout:ana-abc:1')::uuid, md5('package:ana-abc')::uuid, 1, 'B – Costas e bíceps', 'Puxar: dorsais e bíceps, com remadas pesadas.', 'Foco na largura e na espessura das costas. Mantenha o peito aberto e puxe com os cotovelos, não com as mãos. Descanse 90 segundos nas puxadas e remadas e 60 segundos nas roscas.', '[{"category":"strength","name":"Puxada frontal","sets":4,"reps":10,"weightKg":45},{"category":"strength","name":"Remada curvada","sets":4,"reps":10,"weightKg":30,"note":"Tronco a 45°, coluna reta. Se a lombar cansar antes das costas, diminua a carga."},{"category":"strength","name":"Rosca direta","sets":3,"reps":12,"weightKg":12,"note":"Sem balançar o tronco para subir a barra."},{"category":"strength","name":"Rosca martelo","sets":3,"reps":12,"weightKg":10}]'::jsonb)
