insert into public.package_workouts (id, package_id, position, name, summary, description, exercises)
values (md5('package-workout:ana-abc:2')::uuid, md5('package:ana-abc')::uuid, 2, 'C – Pernas e ombros', 'Membros inferiores pesados e desenvolvimento de ombros.', 'O treino mais exigente da semana. Faça 5 minutos de aquecimento na bicicleta e duas séries leves de agachamento antes das séries válidas. Descanse 2 minutos no agachamento e no leg press.', '[{"category":"strength","name":"Agachamento livre","sets":4,"reps":8,"weightKg":50,"note":"Desça até as coxas ficarem paralelas ao chão, com os joelhos na direção dos pés."},{"category":"strength","name":"Leg press","sets":4,"reps":12,"weightKg":120,"note":"Não estenda os joelhos por completo no alto do movimento."},{"category":"strength","name":"Cadeira extensora","sets":3,"reps":15,"weightKg":35},{"category":"strength","name":"Desenvolvimento com halteres","sets":3,"reps":10,"weightKg":14}]'::jsonb)
